sealed class Table
{
    public readonly string Name;
    public readonly List<Column>Columns;
    public readonly int Key;
    public List<List<object?>>Rows = new();
    public Table(string name, List<Column>columns, int key) {
        Name = name;
        Columns = columns;
        Key = key;
    }
    public int Column(string name) => Columns.FindIndex(c => c.Name == name);
}
sealed record Entry(string Name, Table Table, int Offset);
sealed class Scope
{
    public readonly List<Entry>Entries = new();
    int width;
    public void Add(string n, Table t) {
        if (Entries.Any(e => e.Name == n)) throw Error("duplicate table name "+n);
        Entries.Add(new(n, t, width));
        width += t.Columns.Count;
    }
    public string Resolve(Expr e) {
        List<(int Index, string Type)>found = new();
        bool seen = false;
        foreach (Entry p in Entries) if (e.Table == null || e.Table == p.Name) {
            seen = true;
            int i = p.Table.Column(e.Column);
            if (i >= 0) found.Add((p.Offset+i, p.Table.Columns[i].Type));
        }
        if (e.Table != null && !seen) throw Error("unknown table "+e.Table);
        if (found.Count == 0) throw Error("unknown column "+e.Text);
        if (found.Count>1) throw Error("ambiguous column "+e.Column);
        e.Index = found[0].Index;
        return found[0].Type;
    }
}
static bool Compatible(string a, string b) => a == b || a == "NULL" || b == "NULL";
static void Require(string a, string b, string op) {
    if (!Compatible(a, b)) throw Error("type mismatch for "+op);
}
static string Check(Expr e, Scope s, bool allow = false, List<int>? grouped = null, bool inside = false)
{
    if (e.Kind == "literal") return e.Value == null?"NULL":e.Value is long?"INT":"TEXT";
    if (e.Kind == "ref") {
        string type = s.Resolve(e);
        if (grouped != null && !inside && !grouped.Contains(e.Index)) throw Error("column "+e.Text+" is not grouped");
        return type;
    }
    if (e.Kind == "aggregate") {
        if (!allow || inside) throw Error("misuse of aggregate "+e.Op);
static void Condition(Expr? e, Scope s, string name, bool allow = false, List<int>? grouped = null) {
    if (e != null) Require(Check(e, s, allow, grouped), "INT", name);
}
static bool Truth(object? v) => v != null && (long) v != 0;
static object? Evaluate(Expr e, List<object?>row, List<List<object?>>? group = null)
{
    if (e.Kind == "literal") return e.Value;
    if (e.Kind == "ref") return row[e.Index];
static bool Satisfies(Expr? e, List<object?>row, List<List<object?>>? group = null) => e == null || Truth(Evaluate(e, row, group));
static string CountRows(int n) => n+(n == 1?" row":" rows");
static string Written(object? v) => v?.ToString() ?? "NULL";
